output_text:
[
  {
    "id": "checkout_entrance_cart",
    "text": "A shopper is obliged to take the entrance cart before doing the shopping trip.",
    "abstraction": {
      "state_properties": {
        "at_cart_rack": {
          "and": [
            "at(1,5)",
            "cartAt(1,5)"
          ]
        },
        "pushing_cart": "hasCart"
      },
      "events": {
        "take_entrance_cart": {
          "pre": {
            "and": [
              "at_cart_rack",
              "PICKUP_CART"
            ]
          },
          "post": "pushing_cart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "take_entrance_cart"
    }
  },
  {
    "id": "no_item_pickup_without_cart",
    "text": "A shopper is prohibited from picking up shelf items unless they are currently pushing a cart.",
    "abstraction": {
      "state_properties": {
        "without_cart": {
          "not": "hasCart"
        }
      },
      "events": {
        "hand_pickup_attempt": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "without_cart"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "hand_pickup_attempt"
    }
  },
  {
    "id": "no_loose_hand_carrying",
    "text": "A shopper is prohibited from carrying groceries loose in their hands rather than in a cart.",
    "abstraction": {
      "state_properties": {
        "carrying_item_by_hand": "handFull"
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": "carrying_item_by_hand"
    }
  },
  {
    "id": "return_borrowed_cart",
    "text": "After taking a cart, the shopper is obliged to return it to the north-west cart return bay.",
    "abstraction": {
      "state_properties": {
        "cart_return_bay": "at(0,1)",
        "cart_returned": {
          "and": [
            "cartAt(0,1)",
            {
              "not": "hasCart"
            }
          ]
        }
      },
      "events": {
        "take_cart": {
          "pre": {
            "and": [
              "PICKUP_CART",
              "cartAt(1,5)"
            ]
          },
          "post": "hasCart"
        },
        "return_cart_to_bay": {
          "pre": {
            "and": [
              "cart_return_bay",
              "hasCart",
              "LEAVE_CART"
            ]
          },
          "post": "cart_returned"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "take_cart",
      "discharge": "return_cart_to_bay"
    }
  },
  {
    "id": "return_cart_after_collecting_items",
    "text": "Once any required item has been collected using the cart, the cart must eventually be parked in the designated return bay before the trip ends.",
    "abstraction": {
      "state_properties": {
        "at_return_bay": "at(0,1)",
        "cart_parked_in_return_bay": {
          "and": [
            "cartAt(0,1)",
            {
              "not": "hasCart"
            }
          ]
        }
      },
      "events": {
        "collect_item_with_cart": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "hasCart"
            ]
          },
          "post": null
        },
        "park_cart_in_return_bay": {
          "pre": {
            "and": [
              "at_return_bay",
              "LEAVE_CART",
              "hasCart"
            ]
          },
          "post": "cart_parked_in_return_bay"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "collect_item_with_cart",
      "discharge": "park_cart_in_return_bay"
    }
  },
  {
    "id": "no_cart_abandonment_outside_stations",
    "text": "A cart may not be left unattended anywhere except the entrance rack or the north-west return bay.",
    "abstraction": {
      "state_properties": {
        "at_entrance_cart_station": "at(1,5)",
        "at_return_cart_station": "at(0,1)",
        "at_cart_station": {
          "or": [
            "at_entrance_cart_station",
            "at_return_cart_station"
          ]
        },
        "leaving_cart_outside_station": {
          "and": [
            "LEAVE_CART",
            {
              "not": "at_cart_station"
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": "leaving_cart_outside_station"
    }
  },
  {
    "id": "no_exit_with_cart",
    "text": "A shopper is prohibited from leaving the store while still pushing a shopping cart.",
    "abstraction": {
      "state_properties": {
        "pushing_cart": "hasCart"
      },
      "events": {
        "exit_with_cart": {
          "pre": {
            "and": [
              "EXIT",
              "pushing_cart"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "exit_with_cart"
    }
  },
  {
    "id": "cart_free_exit_corridor",
    "text": "Shopping carts are prohibited in the eastern pedestrian exit corridor, so shoppers must leave the cart before entering that area.",
    "abstraction": {
      "state_properties": {
        "eastern_exit_corridor": {
          "or": [
            "at(7,0)",
            "at(7,1)",
            "at(7,2)",
            "at(7,3)",
            "at(7,4)",
            "at(7,5)",
            "at(8,0)",
            "at(8,1)",
            "at(8,2)",
            "at(8,3)",
            "at(8,4)",
            "at(8,5)",
            "at(9,0)",
            "at(9,1)",
            "at(9,2)",
            "at(9,3)",
            "at(9,4)",
            "at(9,5)"
          ]
        },
        "cart_in_exit_corridor": {
          "and": [
            "hasCart",
            "eastern_exit_corridor"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": "cart_in_exit_corridor"
    }
  }
]
